import kotlinx.coroutines.*

fun main() = runBlocking {
    val result = runCatching {
        coroutineScope {
            val a = async { delay(50); error("boom") }
            val b = async { delay(100); "b" }
            launch {
                try { awaitCancellation() } finally { println("c cancelled") }
            }
            b.await() + a.await()
        }
    }
    println(result.exceptionOrNull()?.message)
}

import kotlinx.coroutines.*
import kotlinx.coroutines.flow.*

fun main() = runBlocking {
    // Kotlin, Coroutines, Android, Design, Finale
    val days = flowOf(21, 11, 17, 7, 4)
        .onStart { print("go ") }
        .scan(0) { done, n -> done + n }
        .filter { it > 0 }
    val msg = days.map { "$it" }.reduce { a, b -> "$a,$b" }
    println(if (days.last() == 60) "$msg: done!" else msg)
}
